import{z as i,x as s,o as e,c as p,q as B,j as n,D as A,d as l,s as o,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"工具规划","description":"","frontmatter":{"title":"工具规划","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pl-tool-planning.md","filePath":"llm/pl-tool-planning.md","lastUpdated":1791413859000}'),d={name:"llm/pl-tool-planning.md"};function m(C,E,F,D,c,h){const t=s("Mermaid");return e(),p("div",null,[E[2]||(E[2]=B('<h1 id="工具规划" tabindex="-1">工具规划 <a class="header-anchor" href="#工具规划" aria-label="Permalink to &quot;工具规划&quot;">​</a></h1><div class="epigraph"><p>计划是把依赖、并行与预算写成显式对象；反应式循环里，这些约束只存在于「如果一切顺利」的祈祷中。</p><footer>—— 据 Yao et al., ReAct, ICLR 2023；Xu et al., ReWOO, 2023 的计划—执行对照整理</footer></div><p><a href="/llm/pl-domain-decomposition">上一课</a>把问题拆成接口闭合的子问题，但子问题的解常常不在模型参数里，而在环境里：查库、算数、调 API。规划的对象随之从推理步骤换成工具调用。<a href="/llm/react">多步 ReAct</a> 的反应式循环每看一次观察再决策，能改口；代价是每步一次模型调用、轨迹在工具噪声里晃，依赖与并行这类全局约束守不住。本课写工具规划：把调用序列做成显式的计划对象，交给执行器调度，并处理计划过期。<a href="/llm/plan-vs-react">规划 vs 反应式循环</a>已对照两种控制流的取舍，本课补工程细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反应式的目标函数是局部的：当前一步只对「下一个动作」负责。多跳且调用昂贵时，局部最优表现为重复检索近重复查询、互不依赖的只读调用被迫串行、预算在还没碰到关键步骤时就烧完。这些问题不是「更长的思考」能解决的——上下文里装的是最近观察，不是一张全局依赖图。需要显式对象：计划。</p><p>计划也有对称的失败面。环境会说话：检索为空、API 改版、参数对不上 schema。\\(t=0\\) 写死的十条计划到第 3 条就可能前提作废；不设重规划，执行器会把错误前提执行完；每步都重规划，则退回反应式，还多付了写计划的钱。</p><p><span class="marginnote">术语翻译：「依赖边」就是「谁的输出是谁的输入」这条关系。查「订单表」要用到先查到的「用户 ID」，就从「查用户」向「查订单」连一条边——像菜谱里「先打蛋才能煎蛋」，打乱顺序就做不下去。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计划对象的最小 schema：节点 \\(=\\)（工具名，参数模板，依赖边），整图带预算上限。静态校验在执行前完成：工具名存在于注册表；参数引用闭合——每个引用了观察的参数都有生产者节点，没有悬空占位；权限与成本在预算内。校验不过的计划不进执行器，打回重写，而不是带病上线。</p><p>并行判定是计划直接换钱的点：互不依赖的只读节点并发执行，总延迟从串行的 \\(O(k)\\) 次往返降到关键路径深度 \\(O(d)\\)。参数的前向引用处理剩余的不确定：执行到生产者节点后把观察回填进消费者参数，回填失败走<a href="/llm/pl-reflection-design">上一课</a>的触发器或限次重规划——重规划谓词要显式：观察为空、调用报错、预算过半，三条之外不许改口。</p><p><span class="marginnote">并行的账：\\(10\\) 个互不依赖的检索节点，反应式串行要约 \\(20\\) 次模型调用与 \\(10\\) 次工具往返；计划式是 \\(1\\) 次规划调用，执行器并发打完 \\(10\\) 个请求，延迟只取决于最慢的一个。收益的前提是依赖边真的不存在——错判一条边就把并行收回串行。</span></p>',11)),(e(),n(r,null,{default:A(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%A8%A1%E5%9E%8B%E5%86%99%E8%AE%A1%E5%88%92%EF%BC%9A%E8%8A%82%E7%82%B9%20%2B%20%E4%BE%9D%E8%B5%96%E8%BE%B9%20%2B%20%E9%A2%84%E7%AE%97%22%5D%20--%3E%20CHK%5B%22%E9%9D%99%E6%80%81%E6%A0%A1%E9%AA%8C%EF%BC%9A%E5%AD%98%E5%9C%A8%E6%80%A7%20%2F%20%E5%BC%95%E7%94%A8%E9%97%AD%E5%90%88%20%2F%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20CHK%20--%3E%20BAD%7B%22%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20BAD%20--%3E%7C%E5%90%A6%7C%20W%0A%20%20BAD%20--%3E%7C%E6%98%AF%7C%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%E6%8C%89%E6%8B%93%E6%89%91%E5%BA%8F%E8%B0%83%E5%BA%A6%EF%BC%8C%E5%8F%AA%E8%AF%BB%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20EXEC%20--%3E%20OBS%7B%22%E8%A7%82%E5%AF%9F%E6%AD%A3%E5%B8%B8%E4%B8%94%E9%A2%84%E7%AE%97%E5%86%85%3F%22%7D%0A%20%20OBS%20--%3E%7C%E6%98%AF%7C%20MORE%7B%22%E8%BF%98%E6%9C%89%E8%8A%82%E7%82%B9%3F%22%7D%0A%20%20MORE%20--%3E%7C%E6%98%AF%7C%20EXEC%0A%20%20MORE%20--%3E%7C%E5%90%A6%7C%20DONE%5B%22%E6%B1%87%E6%80%BB%E4%BA%A7%E5%87%BA%22%5D%0A%20%20OBS%20--%3E%7C%E5%90%A6%7C%20REPLAN%5B%22%E9%99%90%E6%AC%A1%E9%87%8D%E8%A7%84%E5%88%92%EF%BC%9A%E6%94%B9%E5%8F%97%E5%BD%B1%E5%93%8D%E5%AD%90%E5%9B%BE%22%5D%0A%20%20REPLAN%20--%3E%20CHK%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"执行器无法挽回坏计划：计划错误是上游错误，执行得越忠实，结果越离谱。所以质量的闸口在静态校验与依赖图本身，不在执行期的「尽力理解」。token 账是计划式的第二笔收益：ReAct 每步把全史带进下一次调用，观察越滚越大；ReWOO 一类的方案把中间观察从逐步推理上下文里拆出，规划一次写完，观察只在回填参数时注入——省的是「每步都读一遍全部历史」的钱。反应式没有白给的优势也在此看清：它的适应力来自随时改口，而改口的价值集中在少数几个真正的意外观察上，把全部步骤都改成反应式，是为 5% 的意外付 100% 的串行。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：\\(10\\) 步任务、每条观察约 \\(500\\) token。反应式第 \\(k\\) 步要重读前 \\(k-1\\) 条观察，全程约 \\(500 \\times (0+1+\\cdots+9) = 22{,}500\\) token 花在重复读取上；计划式观察只在回填时各注入一次，约 \\(500 \\times 10 = 5{,}000\\)。步数越多，这笔账差距越大。")],-1)),(e(),n(r,null,{default:A(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20R%5B%22%E5%8F%8D%E5%BA%94%E5%BC%8F%EF%BC%9A%E6%AF%8F%E6%AD%A5%E9%87%8D%E8%AF%BB%E5%85%A8%E5%8F%B2%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20R1%5B%22%E8%B0%83%E7%94%A8%201%22%5D%20--%3E%20R2%5B%22%E8%B0%83%E7%94%A8%202%EF%BC%9A%E5%B8%A6%E8%A7%82%E5%AF%9F%201%22%5D%20--%3E%20R3%5B%22%E8%B0%83%E7%94%A8%203%EF%BC%9A%E5%B8%A6%E8%A7%82%E5%AF%9F%201%2B2%22%5D%0A%20%20end%0A%20%20subgraph%20P%5B%22%E8%AE%A1%E5%88%92%E5%BC%8F%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%86%99%E5%AE%8C%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20P1%5B%22%E5%AE%8C%E6%95%B4%E8%AE%A1%E5%88%92%E4%B8%80%E6%AC%A1%E7%94%9F%E6%88%90%22%5D%20--%3E%20P2%5B%22%E5%8F%AA%E8%AF%BB%E8%8A%82%E7%82%B9%E5%B9%B6%E5%8F%91%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20P3%5B%22%E8%A7%82%E5%AF%9F%E4%BB%85%E5%9B%9E%E5%A1%AB%E5%8F%82%E6%95%B0%22%5D%0A%20%20end%0A%20%20R1%20-.-%3E%7C%22%E4%B8%8A%E4%B8%8B%E6%96%87%E8%B6%8A%E6%BB%9A%E8%B6%8A%E5%A4%A7%22%7C%20R3%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p>这条对比回答的问题是「钱省在哪」：不是省掉调用次数，而是省掉每一步对历史的重复读取。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>环境不确定性强、探索本身就是任务（不知道该查什么）时，反应式更稳：计划的前提信息还不存在，写计划是猜。循环与数据相关的分支计划难以表达，超出 DAG 的控制流要么模板化、要么退回反应式。散文里的「打算」不是计划：计划必须能被 schema 校验，否则静态检查全部失效。本课只写控制流；工具协议、参数编码与沙箱隔离是 Agent 工程的题目，不在本课展开。</p><p><span class="marginnote">常见误区：初学者容易以为在 prompt 里写「我打算先查 A 再查 B」就是做了规划。实际上这种散文打算无法被校验——没有 schema 就查不出悬空引用，执行器也不敢并发它，「计划」只是一段会更错的话。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计划对象 \\(=\\)（工具、参数模板、依赖边）加预算；静态校验不过不进执行器。</li><li>并行把 \\(O(k)\\) 次往返压成关键路径 \\(O(d)\\)；前提是依赖边判得准。</li><li>参数前向引用靠回填；重规划谓词显式且限次，否则退回反应式。</li><li>执行器无法挽回坏计划；token 账上计划式省的是全史重复读取。</li><li>探索型任务先反应；能校验才算计划，散文不算。</li><li>出处：Yao et al., <em>ReAct</em>, ICLR 2023；Xu et al., <em>ReWOO</em>, 2023；对照见本站<a href="/llm/plan-vs-react">规划 vs 反应式循环</a>。</li></ul>',6))])}const R=i(d,[["render",m]]);export{u as __pageData,R as default};
